<?php
require_once __DIR__.'/../_bootstrap.php';
require_method('GET');$user=require_any_permission(['certificates.issue','audit.view']);
$id=(int)($_GET['id']??0);$sql="SELECT c.*,i.reference inspection_reference,i.status inspection_status,cat.template_family,(SELECT COUNT(*) FROM inspection_attachments a WHERE a.inspection_id=i.id) attachment_count,(SELECT COUNT(*) FROM approvals ap WHERE ap.inspection_id=i.id AND ap.decision='approved') approval_count FROM certificates c JOIN inspections i ON i.id=c.inspection_id JOIN certification_categories cat ON cat.id=i.category_id";$params=[];if($id>0){$sql.=' WHERE c.id=?';$params[]=$id;}$sql.=' ORDER BY c.id DESC LIMIT 500';$q=db()->prepare($sql);$q->execute($params);$rows=[];foreach($q->fetchAll() as $row){$issues=[];$pdf=resolve_storage_path((string)$row['pdf_path']);$qr=resolve_storage_path((string)$row['barcode_path']);if(!$pdf||!is_file($pdf))$issues[]='PDF archive is missing.';if(!$qr||!is_file($qr))$issues[]='QR archive is missing.';if(!preg_match('/^[a-f0-9]{64}$/i',(string)$row['verification_token']))$issues[]='Verification token is invalid.';if((int)$row['approval_count']<1)$issues[]='Approval record is missing.';if((string)$row['template_family']==='chain_block'&&(int)$row['attachment_count']<1)$issues[]='Required Chain Block evidence is missing.';if($issues)$rows[]=['certificate'=>$row,'issues'=>$issues,'repairable'=>true];}respond(['diagnostics'=>$rows]);
